//! Runtime lock file, pinned descriptors, staging and verification.
//!
//! The lock file is generated by `scripts/update-agent-runtimes.mjs` and
//! committed. At runtime this module is the only place that knows how each
//! vendor archive is laid out.

use std::collections::BTreeMap;
use std::io::Read;
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

use super::archive::{extract_format, ArchiveFormat, ExtractOptions, SymlinkPolicy};
use super::{hex, Result, RuntimeError};

/// Minimum Codex version that speaks the ACP bridge orso uses.
pub const CODEX_MINIMUM: &str = "0.156.0";
/// Minimum Claude Code version supported by the pinned adapter.
pub const CLAUDE_MINIMUM: &str = "2.1.232";

/// The five managed runtimes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum RuntimeId {
    Node,
    OpenCode,
    Claude,
    Codex,
    Cursor,
}

impl RuntimeId {
    /// Every runtime in onboarding order.
    pub const ALL: [RuntimeId; 5] = [
        Self::Node,
        Self::OpenCode,
        Self::Claude,
        Self::Codex,
        Self::Cursor,
    ];

    /// Lock file and store directory key.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Node => "node",
            Self::OpenCode => "opencode",
            Self::Claude => "claude",
            Self::Codex => "codex",
            Self::Cursor => "cursor",
        }
    }

    /// Provider id used by `providers.rs`, when this runtime is a chat provider.
    pub fn provider_id(self) -> Option<&'static str> {
        match self {
            Self::Node => None,
            Self::OpenCode => Some("opencode"),
            Self::Claude => Some("claude"),
            Self::Codex => Some("codex"),
            Self::Cursor => Some("cursor"),
        }
    }

    /// Built-in provider id to runtime.
    pub fn from_provider(provider_id: &str) -> Option<Self> {
        match provider_id {
            "opencode" => Some(Self::OpenCode),
            "claude" => Some(Self::Claude),
            "codex" => Some(Self::Codex),
            "cursor" => Some(Self::Cursor),
            _ => None,
        }
    }

    /// Minimum supported CLI version, when the chat protocol needs one.
    pub fn minimum_version(self) -> Option<&'static str> {
        match self {
            Self::Claude => Some(CLAUDE_MINIMUM),
            Self::Codex => Some(CODEX_MINIMUM),
            Self::Node | Self::OpenCode | Self::Cursor => None,
        }
    }
}

impl std::fmt::Display for RuntimeId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl std::str::FromStr for RuntimeId {
    type Err = RuntimeError;

    fn from_str(value: &str) -> Result<Self> {
        match value {
            "node" => Ok(Self::Node),
            "opencode" => Ok(Self::OpenCode),
            "claude" => Ok(Self::Claude),
            "codex" => Ok(Self::Codex),
            "cursor" => Ok(Self::Cursor),
            _ => Err(RuntimeError::NotFound(format!("unknown runtime {value:?}"))),
        }
    }
}

/// macOS build target. Only the two targets the desktop app ships are supported.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum RuntimeTarget {
    DarwinArm64,
    DarwinX64,
}

impl RuntimeTarget {
    /// Lock file artifact key.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::DarwinArm64 => "darwin-arm64",
            Self::DarwinX64 => "darwin-x64",
        }
    }

    /// Node-style architecture name.
    pub fn arch(self) -> &'static str {
        match self {
            Self::DarwinArm64 => "arm64",
            Self::DarwinX64 => "x64",
        }
    }

    /// The target this process runs on, if it is one of ours.
    pub fn current() -> Option<Self> {
        if cfg!(target_os = "macos") {
            if cfg!(target_arch = "aarch64") {
                return Some(Self::DarwinArm64);
            }
            if cfg!(target_arch = "x86_64") {
                return Some(Self::DarwinX64);
            }
        }
        None
    }

    /// Parse a lock key.
    pub fn parse(value: &str) -> Option<Self> {
        match value {
            "darwin-arm64" => Some(Self::DarwinArm64),
            "darwin-x64" => Some(Self::DarwinX64),
            _ => None,
        }
    }
}

impl std::fmt::Display for RuntimeTarget {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

/// Pinned ACP adapter package.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AcpPackage {
    pub package: String,
    pub version: String,
}

/// The committed `agent-runtime.lock.json`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct LockFile {
    pub schema_version: u32,
    pub runtimes: BTreeMap<String, RuntimeLock>,
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub acp: BTreeMap<String, AcpPackage>,
}

/// One runtime's pinned version and per-target artifacts.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RuntimeLock {
    pub version: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sdk_version: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tag: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub repository: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub registry: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub distribution: Option<String>,
    #[serde(default)]
    pub artifacts: BTreeMap<String, RuntimeArtifact>,
}

/// One downloadable build for one target.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RuntimeArtifact {
    /// npm package name, when the artifact is an npm platform tarball.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub package: Option<String>,
    /// Archive file name.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub asset: Option<String>,
    /// Direct download URL. Present for every generated artifact.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub url: Option<String>,
    /// SHA-256 of the downloaded archive.
    pub asset_sha256: String,
    /// SHA-256 of the primary executable after extraction.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub binary_sha256: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub download_bytes: Option<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub installed_bytes: Option<u64>,
    /// Primary executable, relative to the install root.
    pub executable: String,
    /// Every file that should keep an executable mode (defaults to `executable`).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub executables: Vec<String>,
    /// Per-file SHA-256 values for archives with more than one executable file.
    #[serde(default, skip_serializing_if = "BTreeMap::is_empty")]
    pub files: BTreeMap<String, String>,
    /// Archive root, when it is not derivable from the runtime id.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub root: Option<String>,
    /// Leading path components to strip after checking `root`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub strip_components: Option<usize>,
    /// `tar.gz` or `zip`; guessed from the asset name when omitted.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub format: Option<String>,
}

impl RuntimeArtifact {
    /// Archive container for this artifact.
    pub fn archive_format(&self) -> ArchiveFormat {
        self.format
            .as_deref()
            .and_then(ArchiveFormat::parse)
            .unwrap_or_else(|| {
                ArchiveFormat::from_path(Path::new(
                    self.asset
                        .as_deref()
                        .or(self.url.as_deref())
                        .unwrap_or("archive.tar.gz"),
                ))
            })
    }
}

impl LockFile {
    /// Read and parse a lock file.
    pub fn load(path: &Path) -> Result<Self> {
        let text = std::fs::read_to_string(path).map_err(|error| {
            RuntimeError::InvalidLock(format!("cannot read {}: {error}", path.display()))
        })?;
        Self::parse(&text)
    }

    /// Parse lock JSON.
    pub fn parse(text: &str) -> Result<Self> {
        let lock: Self = serde_json::from_str(text)?;
        if lock.schema_version != 1 {
            return Err(RuntimeError::InvalidLock(format!(
                "unsupported schema version {}",
                lock.schema_version
            )));
        }
        Ok(lock)
    }

    /// Pinned runtime metadata.
    pub fn runtime(&self, id: RuntimeId) -> Result<&RuntimeLock> {
        self.runtimes.get(id.as_str()).ok_or_else(|| {
            RuntimeError::NotFound(format!("{} is not in the lock file", id.as_str()))
        })
    }

    /// Pinned artifact for one runtime and target.
    pub fn artifact(&self, id: RuntimeId, target: RuntimeTarget) -> Result<&RuntimeArtifact> {
        self.runtime(id)?
            .artifacts
            .get(target.as_str())
            .ok_or(RuntimeError::UnsupportedTarget(target))
    }

    /// Every runtime present in the lock, in onboarding order.
    pub fn ids(&self) -> Vec<RuntimeId> {
        RuntimeId::ALL
            .into_iter()
            .filter(|id| self.runtimes.contains_key(id.as_str()))
            .collect()
    }
}

/// Fully resolved install recipe for one runtime and target.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RuntimeSpec {
    pub id: RuntimeId,
    pub version: String,
    pub sdk_version: Option<String>,
    pub target: RuntimeTarget,
    pub source_url: String,
    pub format: ArchiveFormat,
    pub expected_root: Option<String>,
    pub strip_components: usize,
    pub executable: String,
    pub executables: Vec<String>,
    pub sha256: String,
    pub binary_sha256: Option<String>,
    pub download_bytes: Option<u64>,
    pub installed_bytes: Option<u64>,
    pub files: BTreeMap<String, String>,
    pub symlinks: SymlinkPolicy,
}

impl RuntimeSpec {
    /// Build the recipe for `id` on `target`.
    pub fn for_target(id: RuntimeId, target: RuntimeTarget, lock: &LockFile) -> Result<Self> {
        let runtime = lock.runtime(id)?;
        let artifact = lock.artifact(id, target)?;
        if artifact.executable.trim().is_empty() {
            return Err(RuntimeError::InvalidLock(format!(
                "{} has an empty executable",
                id.as_str()
            )));
        }

        let expected_root = artifact
            .root
            .clone()
            .or_else(|| default_root(id, &runtime.version, target));
        let strip_components = artifact
            .strip_components
            .unwrap_or_else(|| default_strip(id));
        let mut executables = artifact.executables.clone();
        if executables.is_empty() {
            executables.push(artifact.executable.clone());
        }
        if !executables.iter().any(|exe| exe == &artifact.executable) {
            executables.push(artifact.executable.clone());
        }

        let source_url = artifact.url.clone().unwrap_or_else(|| {
            infer_url(id, runtime, artifact, target).unwrap_or_else(|| {
                format!(
                    "{} (no URL)",
                    artifact.asset.as_deref().unwrap_or("artifact")
                )
            })
        });

        Ok(Self {
            id,
            version: runtime.version.clone(),
            sdk_version: runtime.sdk_version.clone(),
            target,
            source_url,
            format: artifact.archive_format(),
            expected_root,
            strip_components,
            executable: artifact.executable.clone(),
            executables,
            sha256: artifact.asset_sha256.clone(),
            binary_sha256: artifact.binary_sha256.clone(),
            download_bytes: artifact.download_bytes,
            installed_bytes: artifact.installed_bytes,
            files: artifact.files.clone(),
            symlinks: if id == RuntimeId::Node {
                // Node's official tarball links bin/npm and bin/npx to scripts;
                // the descriptor writes real wrappers after extraction.
                SymlinkPolicy::Skip
            } else {
                SymlinkPolicy::Reject
            },
        })
    }

    /// Executable path below an install root.
    pub fn executable_path(&self, root: &Path) -> PathBuf {
        root.join(&self.executable)
    }

    /// Directory that should be prepended to `PATH` so the runtime's helpers
    /// (`npm`, `npx`, bundled `rg`) resolve next to the executable.
    pub fn bin_dir(&self, root: &Path) -> PathBuf {
        let executable = Path::new(&self.executable);
        executable
            .parent()
            .filter(|parent| !parent.as_os_str().is_empty())
            .map(|parent| root.join(parent))
            .unwrap_or_else(|| root.to_path_buf())
    }

    /// Extract into a fresh staging directory and write `orso-install.json`.
    pub fn stage(&self, archive: &Path, dest: &Path) -> Result<InstallManifest> {
        if dest.exists() {
            std::fs::remove_dir_all(dest)?;
        }
        std::fs::create_dir_all(dest)?;
        let options = ExtractOptions {
            expected_root: self.expected_root.clone(),
            strip_components: self.strip_components,
            executables: if self.id == RuntimeId::Claude {
                vec!["claude".into()]
            } else {
                self.executables.clone()
            },
            symlinks: self.symlinks,
            limits: Default::default(),
        };
        extract_format(archive, dest, &options, self.format)?;

        match self.id {
            RuntimeId::Claude => self.stage_claude(dest)?,
            RuntimeId::Node => self.stage_node(dest)?,
            RuntimeId::OpenCode | RuntimeId::Codex | RuntimeId::Cursor => {}
        }

        self.check_pinned_files(dest)?;
        let manifest = self.manifest(dest)?;
        write_manifest(dest, &manifest)?;
        self.verify(dest)?;
        Ok(manifest)
    }

    /// Claude's npm package has `claude` at the root; the install layout keeps
    /// every provider executable under `bin/`.
    fn stage_claude(&self, dest: &Path) -> Result<()> {
        let source = dest.join("claude");
        let bin = dest.join("bin");
        let target = bin.join("claude");
        if source.is_file() {
            std::fs::create_dir_all(&bin)?;
            std::fs::rename(source, &target)?;
        }
        ensure_executable(&target)?;
        Ok(())
    }

    /// Node ships `bin/node` plus symlinks for npm/npx. Since the archive
    /// extractor rejects links, write small wrappers that use the managed node.
    fn stage_node(&self, dest: &Path) -> Result<()> {
        let bin = dest.join("bin");
        std::fs::create_dir_all(&bin)?;
        ensure_executable(&bin.join("node"))?;
        for (name, script) in [
            ("npm", "../lib/node_modules/npm/bin/npm-cli.js"),
            ("npx", "../lib/node_modules/npm/bin/npx-cli.js"),
        ] {
            let path = bin.join(name);
            let body = format!(
                "#!/bin/sh\nexec \"$(dirname \"$0\")/node\" \"$(dirname \"$0\")/{script}\" \"$@\"\n"
            );
            std::fs::write(&path, body)?;
            ensure_executable(&path)?;
        }
        Ok(())
    }

    /// Check the per-file hashes recorded in the lock (Cursor) against the
    /// staged tree.
    fn check_pinned_files(&self, root: &Path) -> Result<()> {
        for (relative, expected) in &self.files {
            let path = root.join(relative);
            let actual = hash_file(&path)?;
            if &actual != expected {
                return Err(RuntimeError::HashMismatch {
                    expected: expected.clone(),
                    actual,
                });
            }
        }
        Ok(())
    }

    /// Build the manifest for a staged tree. Every regular file is hashed.
    pub fn manifest(&self, root: &Path) -> Result<InstallManifest> {
        let mut files = BTreeMap::new();
        for path in walk_files(root)? {
            let relative = path
                .strip_prefix(root)
                .map_err(|_| RuntimeError::InvalidManifest("file outside install root".into()))?;
            let relative = path_key(relative);
            let metadata = std::fs::metadata(&path)?;
            files.insert(
                relative,
                InstallFile {
                    sha256: hash_file(&path)?,
                    size: metadata.len(),
                    mode: file_mode(&path),
                },
            );
        }
        Ok(InstallManifest {
            schema_version: 1,
            runtime: self.id,
            version: self.version.clone(),
            target: self.target.as_str().to_string(),
            source_url: self.source_url.clone(),
            installed_at: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|duration| duration.as_secs())
                .unwrap_or(0),
            executable: self.executable.clone(),
            files,
        })
    }

    /// Verify an installed tree against `orso-install.json` and the lock.
    pub fn verify(&self, root: &Path) -> Result<()> {
        let manifest = read_manifest(root)?;
        if manifest.runtime != self.id || manifest.version != self.version {
            return Err(RuntimeError::InvalidManifest(format!(
                "{} contains {} {}, expected {} {}",
                root.display(),
                manifest.runtime.as_str(),
                manifest.version,
                self.id.as_str(),
                self.version
            )));
        }
        if manifest.target != self.target.as_str() {
            return Err(RuntimeError::InvalidManifest(format!(
                "{} targets {}, expected {}",
                root.display(),
                manifest.target,
                self.target.as_str()
            )));
        }
        for (relative, file) in &manifest.files {
            let path = root.join(relative);
            let metadata = std::fs::metadata(&path).map_err(|error| {
                RuntimeError::InvalidManifest(format!("{relative} is missing: {error}"))
            })?;
            if !metadata.is_file() {
                return Err(RuntimeError::InvalidManifest(format!(
                    "{relative} is not a regular file"
                )));
            }
            if metadata.len() != file.size {
                return Err(RuntimeError::InvalidManifest(format!(
                    "{relative} is {} bytes, expected {}",
                    metadata.len(),
                    file.size
                )));
            }
            let actual = hash_file(&path)?;
            if actual != file.sha256 {
                return Err(RuntimeError::HashMismatch {
                    expected: file.sha256.clone(),
                    actual,
                });
            }
        }
        let executable = root.join(&self.executable);
        if !is_executable(&executable) {
            return Err(RuntimeError::NotExecutable(executable));
        }
        if let Some(expected) = &self.binary_sha256 {
            let actual = hash_file(&root.join(&self.executable))?;
            if &actual != expected {
                return Err(RuntimeError::HashMismatch {
                    expected: expected.clone(),
                    actual,
                });
            }
        }
        self.check_pinned_files(root)?;
        Ok(())
    }

    /// Parse `--version` output for this runtime.
    pub fn parse_version(&self, stdout: &str) -> Result<String> {
        parse_version(self.id, stdout)
    }
}

fn default_root(id: RuntimeId, version: &str, target: RuntimeTarget) -> Option<String> {
    match id {
        RuntimeId::Node => Some(format!("node-v{version}-darwin-{}", target.arch())),
        RuntimeId::OpenCode | RuntimeId::Claude => Some("package".into()),
        RuntimeId::Cursor => Some("dist-package".into()),
        RuntimeId::Codex => None,
    }
}

fn default_strip(id: RuntimeId) -> usize {
    match id {
        RuntimeId::Node | RuntimeId::OpenCode | RuntimeId::Claude | RuntimeId::Cursor => 1,
        RuntimeId::Codex => 0,
    }
}

fn infer_url(
    id: RuntimeId,
    runtime: &RuntimeLock,
    artifact: &RuntimeArtifact,
    target: RuntimeTarget,
) -> Option<String> {
    if let (Some(registry), Some(package), Some(asset)) =
        (&runtime.registry, &artifact.package, &artifact.asset)
    {
        return Some(format!("{registry}/{package}/-/{asset}"));
    }
    if let (Some(repository), Some(tag), Some(asset)) =
        (&runtime.repository, &runtime.tag, &artifact.asset)
    {
        return Some(format!("{repository}/releases/download/{tag}/{asset}"));
    }
    if let (Some(distribution), Some(asset)) = (&runtime.distribution, &artifact.asset) {
        return Some(format!(
            "{distribution}/{}/darwin/{}/{}",
            runtime.version,
            target.arch(),
            asset
        ));
    }
    if id == RuntimeId::Node {
        return artifact
            .asset
            .as_ref()
            .map(|asset| format!("https://nodejs.org/dist/v{}/{asset}", runtime.version));
    }
    None
}

/// One file recorded in `orso-install.json`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct InstallFile {
    pub sha256: String,
    pub size: u64,
    pub mode: u32,
}

/// `orso-install.json`, written beside every staged install.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct InstallManifest {
    pub schema_version: u32,
    pub runtime: RuntimeId,
    pub version: String,
    pub target: String,
    pub source_url: String,
    pub installed_at: u64,
    pub executable: String,
    pub files: BTreeMap<String, InstallFile>,
}

impl InstallManifest {
    /// Installed size in bytes.
    pub fn installed_bytes(&self) -> u64 {
        self.files.values().map(|file| file.size).sum()
    }

    /// Recorded file hash.
    pub fn file_sha256(&self, relative: &str) -> Option<&str> {
        self.files.get(relative).map(|file| file.sha256.as_str())
    }
}

/// Read `orso-install.json` from an install root.
pub fn read_manifest(root: &Path) -> Result<InstallManifest> {
    let path = root.join("orso-install.json");
    let text = std::fs::read_to_string(&path).map_err(|error| {
        RuntimeError::InvalidManifest(format!("cannot read {}: {error}", path.display()))
    })?;
    serde_json::from_str(&text).map_err(|error| {
        RuntimeError::InvalidManifest(format!("cannot parse {}: {error}", path.display()))
    })
}

/// Write `orso-install.json` into an install root.
pub fn write_manifest(root: &Path, manifest: &InstallManifest) -> Result<()> {
    let text = serde_json::to_string_pretty(manifest)
        .map_err(|error| RuntimeError::InvalidManifest(error.to_string()))?;
    std::fs::write(root.join("orso-install.json"), format!("{text}\n"))?;
    Ok(())
}

/// Parse the version token out of a CLI's `--version` output.
pub fn parse_version(id: RuntimeId, stdout: &str) -> Result<String> {
    let token = stdout
        .split_whitespace()
        .map(|token| {
            token.trim_matches(|c: char| {
                matches!(c, '(' | ')' | ',' | ';' | ':' | '"' | '\'' | '[' | ']')
            })
        })
        .map(|token| token.strip_prefix('v').unwrap_or(token))
        .find(|token| {
            token
                .chars()
                .next()
                .is_some_and(|first| first.is_ascii_digit())
                && token.chars().any(|c| c == '.' || c == '-')
        })
        .ok_or_else(|| {
            RuntimeError::NotFound(format!(
                "{} did not report a version: {}",
                id.as_str(),
                stdout.trim()
            ))
        })?;
    Ok(token.to_string())
}

/// Compare dotted numeric versions, treating a pre-release suffix as lower
/// than the release.
pub fn version_cmp(left: &str, right: &str) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    let (left_numbers, left_pre) = split_version(left);
    let (right_numbers, right_pre) = split_version(right);
    let width = left_numbers.len().max(right_numbers.len());
    for index in 0..width {
        let left = left_numbers.get(index).copied().unwrap_or(0);
        let right = right_numbers.get(index).copied().unwrap_or(0);
        match left.cmp(&right) {
            Ordering::Equal => {}
            other => return other,
        }
    }
    match (left_pre, right_pre) {
        (None, None) => Ordering::Equal,
        (None, Some(_)) => Ordering::Greater,
        (Some(_), None) => Ordering::Less,
        (Some(left), Some(right)) => left.cmp(right),
    }
}

fn split_version(value: &str) -> (Vec<u64>, Option<&str>) {
    let value = value.trim().strip_prefix('v').unwrap_or(value);
    let (numbers, pre) = match value.split_once('-') {
        Some((numbers, pre)) => (numbers, Some(pre)),
        None => (value, None),
    };
    let numbers = numbers
        .split('.')
        .map(|part| {
            part.chars()
                .take_while(|c| c.is_ascii_digit())
                .collect::<String>()
                .parse()
                .unwrap_or(0)
        })
        .collect();
    (numbers, pre)
}

/// Whether `version` is at least `minimum`.
pub fn version_meets_minimum(version: &str, minimum: &str) -> bool {
    version_cmp(version, minimum) != std::cmp::Ordering::Less
}

/// SHA-256 of one file.
pub fn hash_file(path: &Path) -> Result<String> {
    let mut file = std::fs::File::open(path)?;
    let mut hasher = Sha256::new();
    let mut buffer = [0u8; 64 * 1024];
    loop {
        let read = file.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        hasher.update(&buffer[..read]);
    }
    Ok(hex(&hasher.finalize()))
}

/// Every regular file below `root`, sorted, rejecting links and special files.
pub fn walk_files(root: &Path) -> Result<Vec<PathBuf>> {
    let mut files = Vec::new();
    walk(root, &mut files)?;
    files.sort();
    Ok(files)
}

fn walk(root: &Path, files: &mut Vec<PathBuf>) -> Result<()> {
    let mut entries = std::fs::read_dir(root)?.collect::<std::io::Result<Vec<_>>>()?;
    entries.sort_by_key(|entry| entry.file_name());
    for entry in entries {
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            walk(&entry.path(), files)?;
        } else if file_type.is_file() {
            files.push(entry.path());
        } else {
            return Err(RuntimeError::Archive(format!(
                "unexpected entry in install: {}",
                entry.path().display()
            )));
        }
    }
    Ok(())
}

fn path_key(path: &Path) -> String {
    path.components()
        .filter_map(|component| match component {
            std::path::Component::Normal(part) => Some(part.to_string_lossy()),
            _ => None,
        })
        .collect::<Vec<_>>()
        .join("/")
}

#[cfg(unix)]
fn file_mode(path: &Path) -> u32 {
    use std::os::unix::fs::PermissionsExt;
    std::fs::metadata(path)
        .map(|metadata| metadata.permissions().mode() & 0o777)
        .unwrap_or(0o644)
}

#[cfg(not(unix))]
fn file_mode(_path: &Path) -> u32 {
    0o644
}

#[cfg(unix)]
fn is_executable(path: &Path) -> bool {
    use std::os::unix::fs::PermissionsExt;
    std::fs::metadata(path)
        .map(|metadata| metadata.is_file() && metadata.permissions().mode() & 0o111 != 0)
        .unwrap_or(false)
}

#[cfg(not(unix))]
fn is_executable(path: &Path) -> bool {
    path.is_file()
}

#[cfg(unix)]
fn ensure_executable(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;
    if !path.is_file() {
        return Err(RuntimeError::NotExecutable(path.to_path_buf()));
    }
    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o755))?;
    Ok(())
}

#[cfg(not(unix))]
fn ensure_executable(path: &Path) -> Result<()> {
    if path.is_file() {
        Ok(())
    } else {
        Err(RuntimeError::NotExecutable(path.to_path_buf()))
    }
}

